CREATE   TRIGGER [HC].[trgUpdateModifiedOnDateForProduct]
   ON HC.Product
   AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT UPDATE(updatedAt)
